{"code":"import json
import pandas as pd

with open("evaluations.json") as f:
    data = json.load(f)

rows = []
for d in data:
    row = {"iter": d["iteration"], "y": d["target_dissimilarity"]}
    for item in d["recipe"]:
        row[item["ingredient"]] = item["fraction"]
    rows.append(row)
df = pd.DataFrame(rows).fillna(0).sort_values("y")
print(df[['iter', 'y', 'soy protein isolate', 'wheat gluten', 'pea protein', 'canola oil', 'coconut oil', 'pea fiber', 'methylcellulose', 'yeast extract', 'flavours']].to_string())
